                c[i][j]=(c[i][j]+a[i][k]*b[k][j]%mod)%mod;
            }
        }
    }
    return c;
}
mat q_pow(mat base,ll n,ll mod)
{
    mat ans(base.size(),vec(base.size()));
    for(int i=0;i<ans.size();i++)ans[i][i]=1;
    while(n)
    {
        if(n&1)ans=mul(ans,base,mod);
        base=mul(base,base,mod);
        n>>=1;
    }
    return ans;
}
